=== vault-grep usage ===
#!/usr/bin/env python3
Usage:
  vault-grep <query>            --root <dir>
                                [--ext .md,.txt]       default: .md,.txt
                                [--top N]              default: 10
                                [--threshold X]        default: 0.0
                                [--rebuild]            re-embed everything
                                [--limit N]            cap files walked
# Consolidated matrix cache. The per-file JSONL above is the source of truth;
# these are a derived, fast-loading mirror of ALL of it: one float32 matrix
# (np.load via mmap, ~instant) + parallel metadata, so a query skips the 34s

=== apple-semantic-match usage ===
#!/usr/bin/env swift
//   apple-semantic-match --dir <folder> [--top N] [--threshold X] [--json]
//   apple-semantic-match --from <fileA> --to <fileB> [--top N] [--threshold X] [--json]
//   apple-semantic-match --query "some text" --to <fileB> [--top N]
// ---- args ----
let flagJSON = args.contains("--json")
let top = Int(opt("--top") ?? "1") ?? 1
let threshold = Double(opt("--threshold") ?? "0") ?? 0
let dir = opt("--dir"); let fromF = opt("--from"); let toF = opt("--to"); let query = opt("--query")

