// fm — talk to Apple's on-device LLM via the FoundationModels framework.
//
// The same model behind Apple Intelligence, running locally on the Neural
// Engine — Apple-native, no Ollama, no pip, no network. macOS 26 (Tahoe) only,
// and only when Apple Intelligence is enabled + the model is downloaded.
//
// Usage:
//   fm "your prompt"            generate a reply (prompt from args)
//   echo "text" | fm            prompt from stdin (e.g. summarize piped text)
//   fm --check                  report model availability, then exit
//   fm --system "..." "prompt"  set system instructions
//   fm --tools --search-dir DIR "prompt"
//                               enable tool-calling. With --search-dir, the
//                               model can call semantic_search to look things
//                               up in the user's notes under DIR (on-device
//                               RAG via vault-grep) and ground its answer.

import Foundation
import FoundationModels

var args = Array(CommandLine.arguments.dropFirst())
func popValue(_ flag: String) -> String? {
    guard let i = args.firstIndex(of: flag), i + 1 < args.count else { return nil }
    let v = args[i + 1]; args.removeSubrange(i...(i + 1)); return v
}
let checkOnly = args.contains("--check"); args.removeAll { $0 == "--check" }
let useTools = args.contains("--tools"); args.removeAll { $0 == "--tools" }
let searchDir = popValue("--search-dir")
let system = popValue("--system")

// ── availability ──
let model = SystemLanguageModel.default
switch model.availability {
case .available:
    if checkOnly { print("available"); exit(0) }
case .unavailable(let reason):
    FileHandle.standardError.write(Data("FoundationModels unavailable: \(reason)\n".utf8))
    exit(3)
@unknown default:
    FileHandle.standardError.write(Data("FoundationModels unavailable (unknown state)\n".utf8))
    exit(3)
}

// ── semantic_search tool — on-device RAG over the user's notes ──
// The model decides when to call it; the call shells out to bin/vault-grep
// (NLEmbedding semantic search over a folder) and returns ranked snippets,
// which the model then grounds its answer in. Read-only, allowlisted — the
// model picks the query string, never a command.
struct SemanticSearchTool: Tool {
    let name = "semantic_search"
    let description = """
    Search the user's own notes and documents for passages related in meaning to a query \
    and return ranked snippets with their file locations. Call this whenever the user asks \
    about their own notes, files, projects, or anything more likely to live in their \
    documents than in general knowledge. Ground the answer in the snippets returned.
    """
    let searchDir: String
    let binDir: String

    @Generable
    struct Arguments {
        @Guide(description: "A short phrase or question describing what to look for")
        var query: String
    }

    func call(arguments: Arguments) async throws -> ToolOutput {
        let p = Process()
        p.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        p.arguments = ["python3", "\(binDir)/vault-grep", arguments.query,
                       "--root", searchDir, "--top", "5"]
        let outPipe = Pipe()
        p.standardOutput = outPipe
        p.standardError = FileHandle.nullDevice    // drop embedding/progress noise
        do { try p.run() } catch {
            return ToolOutput("semantic_search could not run: \(error)")
        }
        p.waitUntilExit()
        let data = outPipe.fileHandleForReading.readDataToEndOfFile()
        let out = (String(data: data, encoding: .utf8) ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return ToolOutput(out.isEmpty ? "No matching passages found in the user's notes." : out)
    }
}

let binDir = ProcessInfo.processInfo.environment["FM_BIN_DIR"]
    ?? "/Users/esaruoho/work/apple/bin"
var tools: [any Tool] = []
if useTools, let dir = searchDir, !dir.isEmpty {
    tools.append(SemanticSearchTool(searchDir: dir, binDir: binDir))
}

// ── prompt (args, else stdin) ──
var prompt = args.filter { !$0.hasPrefix("--") }.joined(separator: " ")
if prompt.isEmpty {
    let data = FileHandle.standardInput.readDataToEndOfFile()
    prompt = String(data: data, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
}
guard !prompt.isEmpty else {
    FileHandle.standardError.write(Data("usage: fm \"prompt\"   (or pipe text on stdin)   ·   fm --check\n".utf8))
    exit(2)
}

// ── generate (async bridged to the CLI via a semaphore) ──
let sema = DispatchSemaphore(value: 0)
var output = ""
var failure: String?
Task {
    do {
        let session: LanguageModelSession
        if !tools.isEmpty {
            session = system.map { LanguageModelSession(tools: tools, instructions: $0) }
                ?? LanguageModelSession(tools: tools)
        } else {
            session = system.map { LanguageModelSession(instructions: $0) }
                ?? LanguageModelSession()
        }
        let result = try await session.respond(to: prompt)
        output = result.content
    } catch {
        failure = "\(error)"
    }
    sema.signal()
}
sema.wait()

if let f = failure {
    FileHandle.standardError.write(Data("fm error: \(f)\n".utf8))
    exit(1)
}
print(output)

