223	        req.timeoutInterval = 20
224	        req.setValue("Mozilla/5.0 (Macintosh) fm", forHTTPHeaderField: "User-Agent")
225	        let (data, resp) = try await URLSession.shared.data(for: req)
226	        let status = (resp as? HTTPURLResponse)?.statusCode ?? 0
227	        guard (200..<300).contains(status) else {
228	            return ToolOutput("Could not fetch \(arguments.url) (HTTP \(status)).")
229	        }
230	        guard let html = String(data: data, encoding: .utf8)
231	                ?? String(data: data, encoding: .isoLatin1) else {
232	            return ToolOutput("Could not decode the page at \(arguments.url).")
233	        }
234	        let title = WebText.title(html)
235	        let text = WebText.strip(html)
236	        let capped = String(text.prefix(6000))   // respect the small context window
237	        var out = title.isEmpty ? "" : "Title: \(title)\n\n"
238	        out += capped
239	        if text.count > capped.count { out += "\n\n[truncated]" }
240	        return ToolOutput(out)
241	    }
242	}
