244	// Tiny Foundation-only HTML → text. Not a full parser; enough to read an article.
245	enum WebText {
246	    static func re(_ s: String, _ p: String, _ rep: String) -> String {
247	        s.replacingOccurrences(of: p, with: rep, options: [.regularExpression, .caseInsensitive])
248	    }
249	    static func title(_ html: String) -> String {
250	        guard let m = html.range(of: "<title[^>]*>(.*?)</title>",
251	                                 options: [.regularExpression, .caseInsensitive]) else { return "" }
252	        let inner = re(re(String(html[m]), "<title[^>]*>", ""), "</title>", "")
253	        return decode(inner).trimmingCharacters(in: .whitespacesAndNewlines)
254	    }
255	    static func strip(_ html: String) -> String {
256	        var s = html
257	        s = re(s, "(?s)<script.*?</script>", " ")
258	        s = re(s, "(?s)<style.*?</style>", " ")
259	        s = re(s, "(?s)<!--.*?-->", " ")
260	        s = re(s, "(?s)<head.*?</head>", " ")
261	        s = re(s, "<(br|/p|/div|/h[1-6]|/li|/tr)[^>]*>", "\n")   // block ends → newline
262	        s = re(s, "<[^>]+>", " ")                                 // remaining tags → space
263	        s = decode(s)
264	        s = re(s, "[ \\t]+", " ")
265	        s = re(s, " *\\n *", "\n")
266	        s = re(s, "\\n{3,}", "\n\n")
267	        return s.trimmingCharacters(in: .whitespacesAndNewlines)
268	    }
269	    static func decode(_ s: String) -> String {
270	        var t = s
271	        let ents = ["&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": "\"", "&#39;": "'",
272	                    "&apos;": "'", "&nbsp;": " ", "&mdash;": "—", "&ndash;": "–",
273	                    "&hellip;": "…", "&rsquo;": "'", "&lsquo;": "'", "&ldquo;": "\"", "&rdquo;": "\""]
274	        for (k, v) in ents { t = t.replacingOccurrences(of: k, with: v) }
275	        return re(t, "&#x?[0-9a-fA-F]+;", " ")   // drop any remaining numeric entities
276	    }
277	}
