21	func escapeHTML(_ s: String) -> String {
22	    var o = s
23	    o = o.replacingOccurrences(of: "&", with: "&amp;")
24	    o = o.replacingOccurrences(of: "<", with: "&lt;")
25	    o = o.replacingOccurrences(of: ">", with: "&gt;")
26	    return o
27	}
