29	/// Regex find/replace with captured groups available to the transform.
30	func regexReplace(_ s: String, _ pattern: String,
31	                  _ opts: NSRegularExpression.Options = [],
32	                  _ transform: ([String]) -> String) -> String {
33	    guard let re = try? NSRegularExpression(pattern: pattern, options: opts) else { return s }
34	    let ns = s as NSString
35	    var result = ""
36	    var last = 0
37	    for m in re.matches(in: s, range: NSRange(location: 0, length: ns.length)) {
38	        result += ns.substring(with: NSRange(location: last, length: m.range.location - last))
39	        var groups: [String] = []
40	        for i in 0..<m.numberOfRanges {
41	            let r = m.range(at: i)
42	            groups.append(r.location == NSNotFound ? "" : ns.substring(with: r))
43	        }
44	        result += transform(groups)
45	        last = m.range.location + m.range.length
46	    }
47	    result += ns.substring(from: last)
48	    return result
49	}
