68	func latexToMathML(_ latex: String, display: Bool) -> String {
69	    let chars = Array(latex)
70	    var i = 0
71	
72	    func wrap(_ s: String) -> String {
73	        // a single element doesn't need an <mrow>; multiple do
74	        return s.contains("</m") && (s.hasPrefix("<mrow") || countTopLevel(s) > 1) ? "<mrow>\(s)</mrow>" : (s.isEmpty ? "<mrow></mrow>" : s)
75	    }
76	    func countTopLevel(_ s: String) -> Int { 2 } // cheap: always wrap groups
77	
78	    func parseBraced() -> String {
79	        if i < chars.count && chars[i] == "{" {
80	            i += 1
81	            let inner = parseSeq(stopAtBrace: true)
82	            if i < chars.count && chars[i] == "}" { i += 1 }
83	            return "<mrow>\(inner)</mrow>"
84	        }
85	        return parseAtom()
86	    }
87	
88	    func parseCommand() -> String {
89	        i += 1 // skip backslash
90	        var name = ""
91	        while i < chars.count && chars[i].isLetter { name.append(chars[i]); i += 1 }
92	        if name == "frac" {
93	            let a = parseBraced(); let b = parseBraced()
94	            return "<mfrac>\(a)\(b)</mfrac>"
95	        }
96	        if name == "sqrt" {
97	            let a = parseBraced()
98	            return "<msqrt>\(a)</msqrt>"
99	        }
100	        if let g = GREEK[name] { return "<mi>\(g)</mi>" }
101	        if let op = OPS[name] { return "<mo>\(op)</mo>" }
102	        if name.isEmpty { i += 1; return "" } // stray backslash
103	        return "<mi>\(name)</mi>"
104	    }
105	
106	    func parseAtom() -> String {
107	        guard i < chars.count else { return "" }
108	        let c = chars[i]
109	        if c == "\\" { return parseCommand() }
110	        if c == "{" { return parseBraced() }
111	        if c.isNumber {
112	            var num = ""
113	            while i < chars.count && (chars[i].isNumber || chars[i] == ".") { num.append(chars[i]); i += 1 }
114	            return "<mn>\(num)</mn>"
115	        }
116	        if c.isLetter {
117	            i += 1
118	            return "<mi>\(c)</mi>"
119	        }
120	        if "+-*/=<>(),.|".contains(c) {
121	            i += 1
122	            let sym = c == "*" ? "×" : String(c)
123	            if c == "(" || c == ")" || c == "|" { return "<mo stretchy=\"false\">\(escapeHTML(sym))</mo>" }
124	            return "<mo>\(escapeHTML(sym))</mo>"
125	        }
126	        if c == " " { i += 1; return "" }
127	        i += 1
128	        return "<mi>\(escapeHTML(String(c)))</mi>"
129	    }
130	
131	    func parseSeq(stopAtBrace: Bool) -> String {
132	        var out = ""
133	        while i < chars.count {
134	            if stopAtBrace && chars[i] == "}" { break }
135	            var atom = parseAtom()
136	            while i < chars.count && (chars[i] == "^" || chars[i] == "_") {
137	                let sup = chars[i] == "^"; i += 1
138	                let arg = parseBraced()
139	                atom = sup ? "<msup>\(atom)\(arg)</msup>" : "<msub>\(atom)\(arg)</msub>"
140	            }
141	            out += atom
142	        }
143	        return out
144	    }
